start_marker = "const BASE_AFFIRMATIONS = ["
start = s.find(start_marker)
if start < 0:
    raise SystemExit("BASE_AFFIRMATIONS start not found")
end_marker = "].map((x, i) => ({ id: `u${i+1}`, theme: x[0], text: x[1] }));"
end = s.find(end_marker, start)
if end < 0:
    # fallback for exact current formatting
    end_marker = "].map((x, i) => ({ id: `u${i+1}`, theme: x[0], text: x[1] }));"
    end = s.find(end_marker, start)
if end < 0:
    raise SystemExit("BASE_AFFIRMATIONS end not found")

segment = s[start:end]
existing = set()
for m in re.finditer(r'\["[^"]+","((?:[^"\\]|\\.)*)"\]', segment):
    try:
        txt = json.loads('"' + m.group(1) + '"')
    except Exception:
        continue
    key = re.sub(r"\s+", " ", txt.strip().lower()).rstrip(".!?…")
    existing.add(key)

added = []
for theme, txt in rows:
    key = re.sub(r"\s+", " ", txt.strip().lower()).rstrip(".!?…")
    if key in existing:
        continue
    existing.add(key)
    added.append((theme, txt))

if not added:
    print("No new affirmations to add")
    raise SystemExit(0)

before = s[:end].rstrip()
after = s[end:]
if not before.endswith(","):
    before += ","

lines = []
for i, (theme, txt) in enumerate(added):
    comma = "," if i < len(added)-1 else ""
    lines.append("      " + json.dumps([theme, txt], ensure_ascii=False, separators=(",", ":")) + comma)

s = before + "\n" + "\n".join(lines) + "\n    " + after.lstrip()
path.write_text(s, encoding="utf-8")
print(f"Added {len(added)} affirmations")
